Future<void> _ask([String? value])async{final prompt=(value??_controller.text).trim();if(prompt.isEmpty||_loading)return;_controller.clear();setState((){_messages.add({'role':'user','text':prompt});_loading=true;});_scrollDown();try{final answer=await _ai.askGeneral(prompt:prompt,history:_messages.map((m)=>ChatMessage(text:m['text']!,isUser:m['role']=='user')).toList(),webSearch:_webSearch);if(mounted)setState(()=>_messages.add({'role':'ai','text':answer}));}catch(e){if(mounted)setState(()=>_messages.add({'role':'ai','text':'$e'}));}finally{if(mounted)setState(()=>_loading=false);_scrollDown();}}
